class Solution {
public:
    int minimumSplits(std::vector<int>& nums) {
        int splits = 1;
        int cur_gcd = nums[0];
        for (int i = 1; i < (int)nums.size(); i++) {
            int new_gcd = std::gcd(cur_gcd, nums[i]);
            if (new_gcd == 1) {
                splits++;
                cur_gcd = nums[i];
            } else {
                cur_gcd = new_gcd;
            }
        }
        return splits;
    }
};

class Solution {
    public int minimumSplits(int[] nums) {
        int splits = 1;
        int curGcd = nums[0];
        for (int i = 1; i < nums.length; i++) {
            int newGcd = gcd(curGcd, nums[i]);
            if (newGcd == 1) {
                splits++;
                curGcd = nums[i];
            } else {
                curGcd = newGcd;
            }
        }
        return splits;
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

var minimumSplits = function(nums) {
    function gcd(a, b) { return b === 0 ? a : gcd(b, a % b); }
    let splits = 1;
    let curGcd = nums[0];
    for (let i = 1; i < nums.length; i++) {
        const newGcd = gcd(curGcd, nums[i]);
        if (newGcd === 1) {
            splits++;
            curGcd = nums[i];
        } else {
            curGcd = newGcd;
        }
    }
    return splits;
};
